class Solution {
  private static int vi(char c) {
    switch (c) {
      case 'a':
        return 0;
      case 'e':
        return 1;
      case 'i':
        return 2;
      case 'o':
        return 3;
      case 'u':
        return 4;
      default:
        return -1;
    }
  }

  // substrings containing all vowels and at least k consonants
  private static long atLeast(String s, int k) {
    int[] cnt = new int[5];
    int have = 0, cons = 0, left = 0;
    long res = 0;
    for (int r = 0; r < s.length(); r++) {
      int v = vi(s.charAt(r));
      if (v >= 0) {
        if (cnt[v]++ == 0) have++;
      } else cons++;
      while (have == 5 && cons >= k) {
        int u = vi(s.charAt(left++));
        if (u >= 0) {
          if (--cnt[u] == 0) have--;
        } else cons--;
      }
      res += left;
    }
    return res;
  }

  public int countOfSubstrings(String word, int k) {
    return (int) (atLeast(word, k) - atLeast(word, k + 1));
  }
}
